   */
  test('paciente com 2 faltas não está suspenso', () => {
    ['2026-09-15 10:00', '2026-10-05 10:00'].forEach((inicio) =>
      inserirConsulta({
        pacienteId: ana.id,
        medicoId: carlos.id,
        inicio,
        fim: inicio.replace(/10:00$/, '10:30'),
        status: 'FALTA',
      }),
