/**
 * Regras puras de validação de cadastro (RN01, RN02, RN03, RN05, RN06, RN07, RN08).
 * Nenhum banco, HTTP ou sistema de arquivos: apenas funções puras de src/domain.
 */
const {
  emailValido,
  senhaValida,
  normalizarCpf,
  cpfValido,
  crmValido,
  calcularIdade,
  validarDataNascimento,
  exigeResponsavel,
  duracaoConsultaValida,
} = require('../../src/domain/validacoes');

const HOJE = new Date(2026, 9, 19); // 2026-10-19 (segunda-feira)

describe('RN01 — formato de e-mail', () => {
  /**
   * @caso CT-UNI-001
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN01
   * @objetivo Aceitar e-mail com nome, arroba e domínio com ponto
   * @resultadoEsperado emailValido devolve true para um endereço bem formado
   */
  test('e-mail bem formado é aceito', () => {
    expect(emailValido('ana@email.com')).toBe(true);
  });

  /**
   * @caso CT-UNI-002
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN01
   * @objetivo Rejeitar e-mail sem o separador de domínio com ponto
   * @resultadoEsperado emailValido devolve false quando falta o domínio com ponto
   */
  test('e-mail sem ponto no domínio é rejeitado', () => {
    expect(emailValido('ana@email')).toBe(false);
  });

  /**
   * @caso CT-UNI-003
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN01
   * @objetivo Rejeitar e-mail vazio ou que não seja texto
   * @resultadoEsperado emailValido devolve false para entrada vazia e para valor não textual
   */
  test('e-mail vazio e valor não textual são rejeitados', () => {
    expect(emailValido('')).toBe(false);
    expect(emailValido(null)).toBe(false);
    expect(emailValido(12345)).toBe(false);
  });

  /**
   * @caso CT-UNI-004
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN01
   * @objetivo Aceitar e-mail com espaços nas pontas após a normalização
   * @resultadoEsperado emailValido devolve true quando só há espaços ao redor
   */
  test('e-mail com espaços nas pontas é aceito após o trim', () => {
    expect(emailValido('  joao.santos@email.com.br ')).toBe(true);
  });

  /**
   * @caso CT-UNI-005
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN01
   * @objetivo Rejeitar e-mail com espaço no meio do endereço
   * @resultadoEsperado emailValido devolve false quando há espaço no nome ou no domínio
   */
  test('e-mail com espaço no meio é rejeitado', () => {
    expect(emailValido('ana pereira@email.com')).toBe(false);
    expect(emailValido('ana@meu email.com')).toBe(false);
  });
});

describe('RN02 — regras de senha', () => {
  /**
   * @caso CT-UNI-006
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN02
   * @objetivo Aceitar senha com 8 caracteres, letra e número
   * @resultadoEsperado senhaValida devolve true para 'Senha123'
   */
  test('senha com 8 caracteres, letras e números é aceita', () => {
    expect(senhaValida('Senha123')).toBe(true);
  });

  /**
   * @caso CT-UNI-007
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN02
   * @objetivo Rejeitar senha de 7 caracteres mesmo com letra e número
   * @resultadoEsperado senhaValida devolve false no valor-limite inferior de comprimento
   */
  test('senha com 7 caracteres é rejeitada', () => {
    expect(senhaValida('Senha12')).toBe(false);
  });

  /**
   * @caso CT-UNI-008
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN02
   * @objetivo Exigir número na senha
   * @resultadoEsperado senhaValida devolve false para senha só com letras
   */
  test('senha sem dígito numérico é rejeitada', () => {
    expect(senhaValida('senhaapenasletras')).toBe(false);
  });

  /**
   * @caso CT-UNI-009
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN02
   * @objetivo Exigir letra na senha
   * @resultadoEsperado senhaValida devolve false para senha só com números
   */
  test('senha sem letra é rejeitada', () => {
    expect(senhaValida('12345678')).toBe(false);
  });

  /**
   * @caso CT-UNI-010
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN02
   * @objetivo Tratar entrada vazia e não textual como senha inválida
   * @resultadoEsperado senhaValida devolve false para '' e para null
   */
  test('senha vazia e não textual são rejeitadas', () => {
    expect(senhaValida('')).toBe(false);
    expect(senhaValida(null)).toBe(false);
  });
});

describe('RN03 — CPF', () => {
  /**
   * @caso CT-UNI-011
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN03
   * @objetivo Aceitar CPF com dígitos verificadores corretos
   * @resultadoEsperado cpfValido devolve true para 529.982.247-25
   */
  test('CPF com dígitos verificadores corretos é aceito', () => {
    expect(cpfValido('529.982.247-25')).toBe(true);
  });

  /**
   * @caso CT-UNI-012
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN03
   * @objetivo Normalizar CPF enviado com pontuação antes de validar
   * @resultadoEsperado normalizarCpf remove ponto e hífen e cpfValido aceita a forma só com dígitos
   */
  test('CPF sem pontuação passa pela mesma validação', () => {
    expect(normalizarCpf('529.982.247-25')).toBe('52998224725');
    expect(cpfValido('52998224725')).toBe(true);
  });

  /**
   * @caso CT-UNI-013
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN03
   * @objetivo Rejeitar CPF cujo dígito verificador não bate
   * @resultadoEsperado cpfValido devolve false para 529.982.247-26
   */
  test('CPF com dígito verificador errado é rejeitado', () => {
    expect(cpfValido('529.982.247-26')).toBe(false);
  });

  /**
   * @caso CT-UNI-014
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN03
   * @objetivo Rejeitar CPF com todos os dígitos iguais
   * @resultadoEsperado cpfValido devolve false para 111.111.111-11
   */
  test('CPF com todos os dígitos iguais é rejeitado', () => {
    expect(cpfValido('111.111.111-11')).toBe(false);
    expect(cpfValido('000.000.000-00')).toBe(false);
  });

  /**
   * @caso CT-UNI-015
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN03
   * @objetivo Rejeitar CPF com quantidade de dígitos diferente de 11
   * @resultadoEsperado cpfValido devolve false para 10 e 12 dígitos
   */
  test('CPF com 10 ou 12 dígitos é rejeitado', () => {
    expect(cpfValido('5299822472')).toBe(false);
    expect(cpfValido('529982247255')).toBe(false);
  });

  /**
   * @caso CT-UNI-016
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN03
   * @objetivo Normalizar entrada não textual para CPF vazio
   * @resultadoEsperado normalizarCpf devolve string vazia para null
   */
  test('normalizarCpf lida com valor nulo', () => {
    expect(normalizarCpf(null)).toBe('');
    expect(normalizarCpf('')).toBe('');
  });
});

describe('RN05 e RN06 — nascimento e responsável', () => {
  /**
   * @caso CT-UNI-017
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05
   * @objetivo Rejeitar data de nascimento no futuro
   * @resultadoEsperado validarDataNascimento devolve mensagem de data futura
   */
  test('nascimento futuro é rejeitado', () => {
    expect(validarDataNascimento('2026-10-20', HOJE)).toBe('Data de nascimento não pode ser futura.');
  });

  /**
   * @caso CT-UNI-018
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN05
   * @objetivo Rejeitar idade acima de 130 anos
   * @resultadoEsperado validarDataNascimento devolve mensagem de idade superior a 130 anos
   */
  test('nascimento que resulta em mais de 130 anos é rejeitado', () => {
    expect(validarDataNascimento('1895-01-01', HOJE)).toBe('Idade não pode ser superior a 130 anos.');
  });

  /**
   * @caso CT-UNI-019
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05
   * @objetivo Aceitar nascimento que resulta exatamente em 130 anos (valor-limite)
   * @resultadoEsperado validarDataNascimento devolve null para 1896-10-19 em relação a 2026-10-19
   */
  test('nascimento de exatamente 130 anos é aceito', () => {
    expect(validarDataNascimento('1896-10-19', HOJE)).toBe(null);
  });

  /**
   * @caso CT-UNI-020
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN05
   * @objetivo Rejeitar nascimento em data inexistente ou com formato errado
   * @resultadoEsperado validarDataNascimento devolve mensagem de formato inválido
   */
  test('nascimento com data inexistente ou formato errado é rejeitado', () => {
    expect(validarDataNascimento('2026-02-30', HOJE)).toBe('Data de nascimento inválida. Use o formato AAAA-MM-DD.');
    expect(validarDataNascimento('19/05/1990', HOJE)).toBe('Data de nascimento inválida. Use o formato AAAA-MM-DD.');
  });

  /**
   * @caso CT-UNI-021
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05
   * @objetivo Aceitar data de nascimento válida no passado
   * @resultadoEsperado validarDataNascimento devolve null
   */
  test('nascimento válido no passado é aceito', () => {
    expect(validarDataNascimento('1990-05-14', HOJE)).toBe(null);
  });

  /**
   * @caso CT-UNI-022
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05, RN06
   * @objetivo Calcular idade considerando se o aniversário já ocorreu no ano corrente
   * @resultadoEsperado calcularIdade devolve 36, 36 e 35 conforme a data de referência
   */
  test('calcularIdade respeita o aniversário do ano', () => {
    const nascimento = new Date(1990, 4, 14); // 1990-05-14
    expect(calcularIdade(nascimento, new Date(2026, 9, 19))).toBe(36);
    expect(calcularIdade(nascimento, new Date(2026, 4, 14))).toBe(36);
    expect(calcularIdade(nascimento, new Date(2026, 4, 13))).toBe(35);
  });

  /**
   * @caso CT-UNI-023
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN06
   * @objetivo Exigir responsável para quem ainda não completou 18 anos
   * @resultadoEsperado exigeResponsavel devolve true para paciente de 16 anos
   */
  test('menor de 18 anos exige responsável', () => {
    expect(exigeResponsavel(new Date(2010, 0, 1), HOJE)).toBe(true);
  });

  /**
   * @caso CT-UNI-024
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN06
   * @objetivo Não exigir responsável para quem completou 18 anos exatamente hoje
   * @resultadoEsperado exigeResponsavel devolve false na fronteira dos 18 anos
   */
  test('paciente de exatamente 18 anos não exige responsável', () => {
    expect(exigeResponsavel(new Date(2008, 9, 19), HOJE)).toBe(false);
  });

  /**
   * @caso CT-UNI-025
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN06
   * @objetivo Exigir responsável um dia antes do aniversário de 18 anos
   * @resultadoEsperado exigeResponsavel devolve true para quem tem 17 anos e 11 meses
   */
  test('paciente de 17 anos e 11 meses ainda exige responsável', () => {
    expect(exigeResponsavel(new Date(2008, 9, 20), HOJE)).toBe(true);
  });
});

describe('RN07 e RN08 — CRM e duração da consulta', () => {
  /**
   * @caso CT-UNI-026
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN07
   * @objetivo Aceitar CRM com 4 a 6 dígitos, barra e UF válida
   * @resultadoEsperado crmValido devolve true para os cinco formatos de exemplo
   */
  test('CRM nos formatos aceitos é validado', () => {
    expect(crmValido('1234/PR')).toBe(true);
    expect(crmValido('11223/MG')).toBe(true);
    expect(crmValido('123456/SP')).toBe(true);
    expect(crmValido('654321/RJ')).toBe(true);
    expect(crmValido('9876/SP')).toBe(true);
  });

  /**
   * @caso CT-UNI-027
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN07
   * @objetivo Rejeitar CRM com menos de 4 ou mais de 6 dígitos
   * @resultadoEsperado crmValido devolve false nos extremos fora da faixa
   */
  test('CRM com 3 ou 7 dígitos é rejeitado', () => {
    expect(crmValido('123/SP')).toBe(false);
    expect(crmValido('1234567/SP')).toBe(false);
  });

  /**
   * @caso CT-UNI-028
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN07
   * @objetivo Rejeitar CRM com UF inexistente ou letra minúscula
   * @resultadoEsperado crmValido devolve false para 'XX' e para 'sp'
   */
  test('CRM com UF inválida é rejeitado', () => {
    expect(crmValido('123456/XX')).toBe(false);
    expect(crmValido('123456/sp')).toBe(false);
  });

  /**
   * @caso CT-UNI-029
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN07
   * @objetivo Rejeitar CRM sem barra ou enviado como número
   * @resultadoEsperado crmValido devolve false para '123456SP' e para 123456
   */
  test('CRM sem barra ou não textual é rejeitado', () => {
    expect(crmValido('123456SP')).toBe(false);
    expect(crmValido(123456)).toBe(false);
  });

  /**
   * @caso CT-UNI-030
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN08
   * @objetivo Aceitar durações múltiplas de 15 entre 15 e 60 minutos
   * @resultadoEsperado duracaoConsultaValida devolve true para 15, 30, 45 e 60
   */
  test('durações válidas são aceitas', () => {
    [15, 30, 45, 60].forEach((min) => expect(duracaoConsultaValida(min)).toBe(true));
  });

  /**
   * @caso CT-UNI-031
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN08
   * @objetivo Rejeitar duração que não é múltipla de 15
   * @resultadoEsperado duracaoConsultaValida devolve false para 20 e 75
   */
  test('duração fora dos múltiplos de 15 é rejeitada', () => {
    expect(duracaoConsultaValida(20)).toBe(false);
    expect(duracaoConsultaValida(75)).toBe(false);
  });

  /**
   * @caso CT-UNI-032
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN08
   * @objetivo Rejeitar duração fora da faixa de 15 a 60 minutos
   * @resultadoEsperado duracaoConsultaValida devolve false para 10 e 61
   */
  test('duração fora da faixa é rejeitada', () => {
    expect(duracaoConsultaValida(10)).toBe(false);
    expect(duracaoConsultaValida(61)).toBe(false);
  });

  /**
   * @caso CT-UNI-033
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN08
   * @objetivo Rejeitar duração fracionária ou enviada como texto
   * @resultadoEsperado duracaoConsultaValida devolve false para 30.5 e para '30'
   */
  test('duração não inteira ou textual é rejeitada', () => {
    expect(duracaoConsultaValida(30.5)).toBe(false);
    expect(duracaoConsultaValida('30')).toBe(false);
  });
});

backend/__testes__/api/autenticacao.test.source:
/**
 * API de autenticação (RF01, RF02), bloqueio por tentativas (RN04)
 * e segurança de token/senha (RNF01, RNF02).
 * Relógio fixado em 2026-10-19 08:00 (segunda-feira).
 */
const request = require('supertest');
const jwt = require('jsonwebtoken');
const clock = require('../../src/utils/clock');
const config = require('../../src/config');
const { abrirBanco } = require('../../src/db/connection');
const { semear } = require('../../src/db/seed');
const { criarApp } = require('../../src/app');

let db;
let app;

beforeEach(() => {
  clock.definirAgora(new Date('2026-10-19T08:00:00'));
  db = abrirBanco(':memory:');
  semear(db);
  app = criarApp({ db });
});

afterEach(() => {
  clock.definirAgora(null);
  db.close();
});

function tokenDe(email, senha = 'Senha123') {
  return request(app)
    .post('/api/auth/login')
    .send({ email, senha })
    .then((res) => res.body.token);
}

function idDoUsuario(email) {
  return app.locals.servicos.repos.usuarios.buscarPorEmail(email).id;
}

describe('RF01 — login e sessão', () => {
  /**
   * @caso CT-API-001
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF01.1
   * @objetivo Fazer login com e-mail e senha corretos
   * @resultadoEsperado a resposta é 200 com token e os dados públicos do usuário
   */
  test('login com credenciais válidas devolve token e usuário', async () => {
    const res = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(res.status).toBe(200);
    expect(typeof res.body.token).toBe('string');
    expect(res.body.usuario).toEqual({
      id: expect.any(Number),
      nome: 'Ana Pereira',
      email: 'ana@email.com',
      perfil: 'PACIENTE',
      pacienteId: expect.any(Number),
    });
  });

  /**
   * @caso CT-API-002
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.1, RNF02
   * @objetivo Emitir token com validade de 8 horas
   * @resultadoEsperado a diferença entre exp e iat do token é 28800 segundos
   */
  test('token emitido expira em 8 horas', async () => {
    const token = await tokenDe('recepcao@clinica.com');
    const payload = jwt.decode(token);
    expect(payload.exp - payload.iat).toBe(8 * 3600);
  });

  /**
   * @caso CT-API-003
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF01.3
   * @objetivo Devolver os dados do usuário logado
   * @resultadoEsperado o GET /api/auth/me responde 200 com e-mail e perfil
   */
  test('GET /api/auth/me devolve o usuário do token', async () => {
    const token = await tokenDe('ana@email.com');
    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${token}`);
    expect(res.status).toBe(200);
    expect(res.body.email).toBe('ana@email.com');
    expect(res.body.perfil).toBe('PACIENTE');
    expect(res.body).not.toHaveProperty('senhaHash');
  });

  /**
   * @caso CT-API-004
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.2, RNF02
   * @objetivo Exigir token nas rotas protegidas
   * @resultadoEsperado a requisição sem cabeçalho responde 401 NAO_AUTENTICADO
   */
  test('rota protegida sem token responde 401', async () => {
    const res = await request(app).get('/api/auth/me');
    expect(res.status).toBe(401);
    expect(res.body).toEqual({ erro: { codigo: 'NAO_AUTENTICADO', mensagem: 'Autenticação necessária.' } });
  });

  /**
   * @caso CT-API-005
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.2, RNF02
   * @objetivo Recusar token que não foi assinado pelo servidor
   * @resultadoEsperado a resposta é 401 com a mensagem de token inválido ou expirado
   */
  test('token forjado responde 401', async () => {
    const forjado = jwt.sign({ sub: 1, perfil: 'RECEPCAO' }, 'outro-segredo');
    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${forjado}`);
    expect(res.status).toBe(401);
    expect(res.body.erro.mensagem).toBe('Token inválido ou expirado.');
  });

  /**
   * @caso CT-API-006
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.2, RNF02
   * @objetivo Recusar token cujo prazo de validade já venceu
   * @resultadoEsperado a resposta é 401 NAO_AUTENTICADO
   */
  test('token expirado responde 401', async () => {
    const expirado = jwt.sign({ sub: idDoUsuario('ana@email.com'), perfil: 'PACIENTE' }, config.jwtSegredo, {
      expiresIn: '-10s',
    });
    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${expirado}`);
    expect(res.status).toBe(401);
    expect(res.body.erro.codigo).toBe('NAO_AUTENTICADO');
  });

  /**
   * @caso CT-API-007
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RF01.2, RNF02
   * @objetivo Recusar cabeçalho Authorization com formato diferente de Bearer
   * @resultadoEsperado a resposta é 401 NAO_AUTENTICADO
   */
  test('cabeçalho sem Bearer responde 401', async () => {
    const token = await tokenDe('ana@email.com');
    const res = await request(app).get('/api/auth/me').set('Authorization', `Token ${token}`);
    expect(res.status).toBe(401);
    expect(res.body.erro.codigo).toBe('NAO_AUTENTICADO');
  });

  /**
   * @caso CT-API-008
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF01.1
   * @objetivo Recusar login que não informou e-mail ou senha
   * @resultadoEsperado a resposta é 400 VALIDACAO pedindo e-mail e senha
   */
  test('login sem senha responde 400', async () => {
    const res = await request(app).post('/api/auth/login').send({ email: 'ana@email.com' });
    expect(res.status).toBe(400);
    expect(res.body).toEqual({ erro: { codigo: 'VALIDACAO', mensagem: 'Informe e-mail e senha.' } });
  });
});

describe('RN04 — bloqueio após tentativas erradas', () => {
  /**
   * @caso CT-API-009
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN04
   * @objetivo Recusar a senha correta depois de cinco falhas seguidas
   * @resultadoEsperado a resposta é 423 CONTA_BLOQUEADA com o horário do desbloqueio
   */
  test('quinta falha de login bloqueia a conta', async () => {
    for (let i = 0; i < 4; i += 1) {
      const falha = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Errada123' });
      expect(falha.status).toBe(401);
    }
    const quinta = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Errada123' });
    expect(quinta.status).toBe(423);
    expect(quinta.body.erro.codigo).toBe('CONTA_BLOQUEADA');

    const correta = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(correta.status).toBe(423);
    expect(correta.body.erro.mensagem).toContain('Conta bloqueada por excesso de tentativas.');
  });

  /**
   * @caso CT-API-010
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN04
   * @objetivo Liberar a conta 15 minutos após o bloqueio
   * @resultadoEsperado o login com a senha correta volta a responder 200
   */
  test('bloqueio termina após 15 minutos', async () => {
    for (let i = 0; i < 5; i += 1) {
      await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Errada123' });
    }
    const bloqueado = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(bloqueado.status).toBe(423);

    clock.definirAgora(new Date('2026-10-19T08:16:00'));
    const liberado = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(liberado.status).toBe(200);
  });

  /**
   * @caso CT-API-011
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN04
   * @objetivo Zerar o contador de falhas quando o login é correto
   * @resultadoEsperado após um sucesso, novas falhas voltam a responder 401 e não 423
   */
  test('login correto zera o contador de tentativas', async () => {
    for (let i = 0; i < 4; i += 1) {
      await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Errada123' });
    }
    const sucesso = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(sucesso.status).toBe(200);

    const novaFalha = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Errada123' });
    expect(novaFalha.status).toBe(401);
    expect(novaFalha.body.erro.codigo).toBe('NAO_AUTENTICADO');
  });
});

describe('RF01 e RF02 — respostas públicas e cadastro', () => {
  /**
   * @caso CT-API-012
   * @nivel api
   * @atributo seguranca
   * @subatributo confidencialidade
   * @requisito RNF01
   * @objetivo Nunca devolver o hash da senha pela API
   * @resultadoEsperado a resposta do login e a do cadastro não contêm senha nem hash
   */
  test('respostas do login e do cadastro não expõem a senha', async () => {
    const login = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    const textoLogin = JSON.stringify(login.body);
    expect(textoLogin).not.toContain('senhaHash');
    expect(textoLogin).not.toContain('senha');

    const registro = await request(app).post('/api/auth/registro').send({
      nome: 'Paula Nunes',
      email: 'paula@email.com',
      senha: 'Senha123',
      cpf: '12345678909',
      dataNascimento: '1992-03-10',
      telefone: '(11) 91234-5678',
    });
    expect(registro.status).toBe(201);
    const textoRegistro = JSON.stringify(registro.body);
    expect(textoRegistro).not.toContain('senhaHash');
    expect(textoRegistro).not.toContain('Senha123');
  });

  /**
   * @caso CT-API-013
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF02.1
   * @objetivo Permitir auto-cadastro público de paciente
   * @resultadoEsperado a resposta é 201 com o paciente criado e perfil PACIENTE
   */
  test('auto-cadastro de paciente responde 201', async () => {
    const res = await request(app).post('/api/auth/registro').send({
      nome: 'Paula Nunes',
      email: 'paula@email.com',
      senha: 'Senha123',
      cpf: '12345678909',
      dataNascimento: '1992-03-10',
      telefone: '(11) 91234-5678',
    });
    expect(res.status).toBe(201);
    expect(res.body.nome).toBe('Paula Nunes');
    expect(res.body.email).toBe('paula@email.com');
    expect(res.body.ativo).toBe(true);
  });

  /**
   * @caso CT-API-014
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN01
   * @objetivo Recusar auto-cadastro com e-mail já usado
   * @resultadoEsperado a resposta é 409 CONFLITO de e-mail já cadastrado
   */
  test('auto-cadastro com e-mail duplicado responde 409', async () => {
    const res = await request(app).post('/api/auth/registro').send({
      nome: 'Paula Nunes',
      email: 'ana@email.com',
      senha: 'Senha123',
      cpf: '12345678909',
      dataNascimento: '1992-03-10',
    });
    expect(res.status).toBe(409);
    expect(res.body).toEqual({ erro: { codigo: 'CONFLITO', mensagem: 'E-mail já cadastrado.' } });
  });

  /**
   * @caso CT-API-015
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN02
   * @objetivo Recusar auto-cadastro com senha fraca
   * @resultadoEsperado a resposta é 400 VALIDACAO com a regra de senha
   */
  test('auto-cadastro com senha fraca responde 400', async () => {
    const res = await request(app).post('/api/auth/registro').send({
      nome: 'Paula Nunes',
      email: 'paula@email.com',
      senha: '1234567',
      cpf: '12345678909',
      dataNascimento: '1992-03-10',
    });
    expect(res.status).toBe(400);
    expect(res.body.erro.mensagem).toBe('Senha deve ter no mínimo 8 caracteres, com letras e números.');
  });

  /**
   * @caso CT-API-016
   * @nivel api
   * @atributo seguranca
   * @subatributo responsabilizacao
   * @requisito RN21
   * @objetivo Recusar login de conta desativada pela recepção
   * @resultadoEsperado a resposta é 403 SEM_PERMISSAO orientando procurar a recepção
   */
  test('login em conta inativa responde 403', async () => {
    app.locals.servicos.repos.usuarios.definirAtivo(idDoUsuario('ana@email.com'), false);
    const res = await request(app).post('/api/auth/login').send({ email: 'ana@email.com', senha: 'Senha123' });
    expect(res.status).toBe(403);
    expect(res.body).toEqual({ erro: { codigo: 'SEM_PERMISSAO', mensagem: 'Conta inativa. Procure a recepção.' } });
  });

  /**
   * @caso CT-API-017
   * @nivel api
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RNF02
   * @objetivo Invalidar o token de conta desativada depois do login
   * @resultadoEsperado o GET /api/auth/me responde 401 NAO_AUTENTICADO
   */
  test('token de conta desativada responde 401', async () => {
    const token = await tokenDe('ana@email.com');
    app.locals.servicos.repos.usuarios.definirAtivo(idDoUsuario('ana@email.com'), false);
    const res = await request(app).get('/api/auth/me').set('Authorization', `Bearer ${token}`);
    expect(res.status).toBe(401);
    expect(res.body.erro.mensagem).toBe('Usuário inexistente ou inativo.');
  });

  /**
   * @caso CT-API-018
   * @nivel api
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RF01.1
   * @objetivo Responder 401 igual para senha errada e para e-mail inexistente
   * @resultadoEsperado os dois casos devolvem a mesma mensagem, sem revelar o campo
   */
  test('senha errada e e-mail inexistente têm a mesma resposta', async () => {
    const senhaErrada = await request(app)
      .post('/api/auth/login')
      .send({ email: 'ana@email.com', senha: 'OutraSenha1' });
    const semConta = await request(app)
      .post('/api/auth/login')
      .send({ email: 'ninguem@email.com', senha: 'OutraSenha1' });

    expect(senhaErrada.status).toBe(401);
    expect(semConta.status).toBe(401);
    expect(senhaErrada.body).toEqual(semConta.body);
    expect(senhaErrada.body.erro.mensagem).toBe('E-mail ou senha inválidos.');
  });
});

